  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 14px;
  margin-bottom: 20px;
}

.recent-detail-grid div,
.recent-related-box {
  padding: 14px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.025);
  border: 1px solid rgba(255, 255, 255, 0.065);
}

.recent-detail-grid strong,
.recent-related-box strong {
  font-size: 14px;
  font-weight: 600;
}

.recent-related-box {
  margin-bottom: 20px;
}

.recent-detail-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.recent-detail-actions button {
  padding: 10px 14px;
  border-radius: 999px;
  color: #fff;
  cursor: pointer;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.1);
  font-size: 13px;
}

.recent-detail-actions .primary-small {
