.capture-modal-shell {
  width: min(960px, calc(100vw - 32px));
  max-height: calc(100vh - 32px);
  overflow-y: auto;
  background: #ffffff;
  border: 1px solid #e7e3dc;
  border-radius: 24px;
  box-shadow: 0 28px 80px rgba(17, 17, 17, 0.18);
  padding: 28px;
}

.capture-modal-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
  padding-bottom: 18px;
  margin-bottom: 22px;
  border-bottom: 1px solid #ece7df;
}

.capture-modal-header h2 {
  margin: 0;
  font-size: 22px;
  line-height: 1.2;
  font-weight: 700;
  color: #111111;
}

.capture-modal-body {
  width: 100%;
}

.capture-modal-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 18px;
  width: 100%;
  align-items: start;
}

.capture-field {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
}

.capture-field-full {
  grid-column: 1 / -1;
}

.capture-field label {
  font-size: 13px;
  font-weight: 600;
  line-height: 1.4;
  color: #3e3e3e;
}

.capture-field input,
.capture-field textarea {
  width: 100%;
  border: 1px solid #d9d4cb;
  border-radius: 16px;
  background: #ffffff;
  color: #111111;
  font-size: 15px;
  line-height: 1.45;
